/**
 * Offline deploy manifest (workstream Wd of
 * `docs/agent-serve/agent-sdk-event-ingress-plan.md`, Wd-0/Wd-1).
 *
 * The manifest is every piece of deployment metadata that is statically
 * derivable from the agent project — extracted at build/deploy time, with no
 * VM, no engine, and no network — so the control plane can store it before
 * any pod starts and keep answering metadata questions while a deployment is
 * offline or hibernated.
 *
 * Two layers with different stability contracts:
 *
 * - `declarations` is the **versioned wire contract** consumed by the
 *   control plane (Wd-2): per-channel event capabilities, egress domains,
 *   and public route paths. Validated by {@link agentDeployManifestV1Schema};
 *   the CP stores these as columns / column views. Repos are deliberately
 *   NOT here — which repos a deployment watches is per-instance deploy
 *   configuration, not a property of the code.
 * - `info` is the full static project description — the same payload the
 *   engine serves at `GET /v1/info` (`projectInfo`). Stored opaquely by the
 *   CP so `/v1/info`-class reads can be served for offline deployments
 *   (Wd-5). Its shape evolves with the SDK and is intentionally not pinned
 *   by the wire schema beyond "is an object".
 *
 * Event derivation note: each mounted channel publishes its event set in its
 * own `channels[].eventTypes` declaration. A project with no GitHub channel
 * subscribes to no GitHub events, regardless of configured repository scope.
 * Keep that capability per-channel: do not reintroduce a provider-wide event
 * union for control-plane consumers.
 */
import * as z from "zod/v4";
import { catchAuthDeclaration, isPublicEndpointPolicy, } from "../channels.js";
import { githubChannelCredentialSecretNames, isCursorAccountGitHubChannel, } from "../channels/github/github-channel.js";
import { pagerDutyChannelCredentialSecretNames, pagerDutyChannelSecretAlternatives, } from "../channels/pagerduty/pagerduty-channel.js";
import { isCursorHostedStorage } from "../storage-backends/cursor-hosted.js";
import { channelArchitectureError } from "./channel-architecture.js";
import { applyAgentContinuationDefaults, channelContinuationIdentity, channelDeclaredEventTypes, handshakeChannelContinuation, } from "./continuation-channel.js";
import { CONTINUATION_SELECTORS } from "./continuation-identity.js";
import { projectInfo } from "./discovery.js";
import { packageGitSha, packageVersion } from "./distribution.js";
import { peerDeploySlugs } from "./peer-connections.js";
export const DEPLOY_MANIFEST_VERSION = 1;
/**
 * Versioned wire contract for the CP-consumed declaration fields. Kept
 * module-private (the package builds with isolated declarations); consumers
 * use {@link parseAgentDeployManifest} and the explicit interfaces below.
 */
const continuationIdentitySchema = z.enum(CONTINUATION_SELECTORS);
const CATCH_MAX_ROUTES = 32;
const CATCH_MAX_AUTH_POLICIES = 4;
const catchDeclarationSchema = z.object({
    routes: z
        .array(z.object({
        method: z.enum(["GET", "POST", "PUT", "PATCH", "DELETE"]),
        path: z.string().min(1).max(1024),
    }))
        .min(1)
        .max(CATCH_MAX_ROUTES),
    auth: z
        .array(z.discriminatedUnion("kind", [
        z.object({
            kind: z.literal("header"),
            header: z.string().min(1).max(128),
            secret: z.string().min(1).max(64),
        }),
        z.object({
            kind: z.literal("hmac-sha256"),
            header: z.string().min(1).max(128),
            secret: z.string().min(1).max(64),
            prefix: z.string().max(32).optional(),
            separator: z.string().min(1).max(8).optional(),
        }),
        z.object({ kind: z.literal("public") }),
    ]))
        .min(1)
        .max(CATCH_MAX_AUTH_POLICIES),
});
const slackReplyDeclarationSchema = z.object({
    mode: z.literal("agentic"),
    ack: z.string().regex(/^[a-z0-9_+-]{1,50}$/),
    placeholder: z
        .string()
        .regex(/^(?!.*(?:<!|<@))[^\r\n]{2,80}$/)
        .optional(),
});
/**
 * Hosted v2 schedule ids name the reserved `schedule:<id>` hosted-admission
 * channel, which the control plane bounds at 128 characters.
 */
const SCHEDULE_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._/-]{0,99}$/;
const MAX_SCHEDULES = 64;
const scheduleDeclarationSchema = z.object({
    id: z
        .string()
        .regex(SCHEDULE_ID_PATTERN, "hosted v2 schedule names are 1-100 letters, digits, `.`, `_`, `-`, or `/`, starting with a letter or digit")
        .refine((id) => !id.split("/").includes(".."), "must not contain `..` segments"),
    cron: z.string().min(1).max(128),
    kind: z.enum(["markdown", "run"]),
});
const agentDeployManifestV1Schema = z.object({
    manifestVersion: z.literal(DEPLOY_MANIFEST_VERSION),
    generatedAtMs: z.number().int().nonnegative(),
    cliVersion: z.string().min(1),
    cliGitSha: z
        .string()
        .regex(/^[0-9a-f]{40,64}$/)
        .optional(),
    declarations: z.object({
        egressDomains: z.array(z.string().min(1)).max(64),
        publicRoutePaths: z.array(z.string().min(1)).max(64),
        frameworkStorage: z.enum(["cursor-hosted", "other", "none"]).optional(),
        architecture: z.enum(["v1", "v2"]).optional(),
        persistent: z.boolean().optional(),
        image: z.string().min(2).max(64).optional(),
        channels: z
            .array(z.object({
            id: z.string().min(1).max(128),
            kind: z.string().min(1).max(32).optional(),
            eventTypes: z.array(z.string().min(1).max(64)).max(64).optional(),
            continuation: continuationIdentitySchema,
            catch: catchDeclarationSchema.optional(),
            slackReply: slackReplyDeclarationSchema.optional(),
            slackChannelPosts: z.array(z.string().min(1).max(80)).max(64).optional(),
        }))
            .max(64),
        schedules: z.array(scheduleDeclarationSchema).max(MAX_SCHEDULES).optional(),
        peers: z.array(z.string().min(1).max(128)).max(64).optional(),
    }),
    // Full `projectInfo` payload — opaque to the wire contract.
    info: z.record(z.string(), z.unknown()),
});
/**
 * Extract the offline deploy manifest from a loaded project. Pure: no
 * network, no filesystem beyond what `loadAgentProject` already read.
 */
export function buildAgentDeployManifest(project, options) {
    applyAgentContinuationDefaults(project);
    const channels = project.channels.map((channel) => {
        const architectureError = channelArchitectureError(project.agent.architecture, channel.definition);
        if (architectureError !== undefined) {
            throw new Error(`channels/${channel.id}: ${architectureError}`);
        }
        const handshake = handshakeChannelContinuation(channel);
        if (!handshake.ok) {
            throw new Error(handshake.error);
        }
        const kind = channel.definition.meta?.kind;
        const meta = channel.definition.meta;
        const declaredEvents = channelDeclaredEventTypes(channel.definition.meta);
        const eventTypes = declaredEvents === undefined ? undefined : [...declaredEvents].sort();
        return {
            id: channel.id,
            kind,
            eventTypes,
            continuation: channelContinuationIdentity(channel.definition),
            catch: channelCatchDeclaration(channel.definition),
            ...(kind === "slack" && meta?.slackReply !== undefined
                ? { slackReply: meta.slackReply }
                : {}),
            ...(kind === "slack" && meta?.slackChannelPosts !== undefined
                ? { slackChannelPosts: [...meta.slackChannelPosts] }
                : {}),
        };
    });
    // Same mapping as `july deploy` (cli-deploy.ts): channels declared public
    // via `publicEndpoint()` become alias-token-free route prefixes.
    const publicRoutePaths = project.channels
        .filter((channel) => (channel.definition.auth ?? []).some(isPublicEndpointPolicy))
        .map((channel) => `/v1/channels/${channel.id}`);
    const manifest = {
        manifestVersion: DEPLOY_MANIFEST_VERSION,
        generatedAtMs: options?.nowMs ?? Date.now(),
        cliVersion: options?.cliVersion ?? packageVersion(),
        cliGitSha: options?.cliGitSha ?? packageGitSha(),
        declarations: {
            egressDomains: [...(project.agent.hosting?.egressDomains ?? [])],
            publicRoutePaths,
            // Deploy manifests describe Cursor-hosted deployments. When the agent
            // authors no storage, framework-storage-selection.ts injects the
            // platform Cursor-hosted mirror for both v1 and v2.
            frameworkStorage: project.storage === undefined
                ? "cursor-hosted"
                : isCursorHostedStorage(project.storage)
                    ? "cursor-hosted"
                    : "other",
            ...(project.agent.architecture === undefined
                ? {}
                : { architecture: project.agent.architecture }),
            ...(project.agent.hosting?.image === undefined ? {} : { image: project.agent.hosting.image }),
            channels,
            // v1 calendars stay engine-synced at boot; only v2 compiles declarations.
            schedules: project.agent.architecture === "v2"
                ? project.schedules.map((schedule) => ({
                    id: schedule.name,
                    cron: schedule.cron,
                    kind: schedule.kind,
                }))
                : undefined,
            peers: peerDeploySlugs(project),
        },
        info: projectInfo(project),
    };
    const validation = agentDeployManifestV1Schema.safeParse(manifest);
    if (!validation.success) {
        const issues = validation.error.issues
            .map((issue) => `${issue.path.join(".")}: ${issue.message}`)
            .join("; ");
        throw new Error(`Invalid Agent SDK deploy manifest: ${issues}`);
    }
    return manifest;
}
/**
 * Catch declaration for one authored channel: its routes, gated by the
 * catch-capable policies in its auth chain (`sharedSecretAuth`,
 * `hmacSignatureAuth`, or `publicEndpoint()` for handler-verified routes).
 * A routed channel with none of those declares nothing and is not reachable
 * through the catch API.
 */
export function channelCatchDeclaration(definition) {
    const routes = definition.routes ?? [];
    if (routes.length === 0) {
        return undefined;
    }
    // A cursorAccount channel receives its deliveries through Cursor's own
    // GitHub App on the webhook fleets, never through a direct catch. The
    // `GITHUB_WEBHOOK_SECRET` fallback still shapes its local route policy,
    // but that must not open a second, direct door on the control plane.
    if (isCursorAccountGitHubChannel(definition)) {
        return undefined;
    }
    const declared = (definition.auth ?? [])
        .map(catchAuthDeclaration)
        .filter((declaration) => declaration !== undefined);
    if (declared.length === 0) {
        return undefined;
    }
    // An auth chain is any-of, so `publicEndpoint()` beside secret policies
    // admits everything locally and on the control plane alike. Declare one
    // `public` entry (the control plane then decrypts nothing) but keep the
    // shared-secret header policies next to it: they are what the control
    // plane uses to strip those header values before the request is
    // claim-checked, and senders keep sending the secret regardless of
    // whether anything still checks it. HMAC policies carry body digests,
    // not secrets, so nothing is lost by dropping them.
    const isPublic = declared.some((policy) => policy.kind === "public");
    const auth = isPublic
        ? [{ kind: "public" }, ...declared.filter((policy) => policy.kind === "header")]
        : declared;
    if (routes.length > CATCH_MAX_ROUTES) {
        if (isPublic) {
            // publicEndpoint() channels deployed before catch existed; they stay
            // reachable the way they were (not through catch) rather than
            // failing the deploy.
            return undefined;
        }
        throw new Error(`Catch channels may declare at most ${CATCH_MAX_ROUTES} routes (got ${routes.length}).`);
    }
    if (auth.length > CATCH_MAX_AUTH_POLICIES) {
        throw new Error(isPublic
            ? `Catch channels may declare at most ${CATCH_MAX_AUTH_POLICIES} auth policies; publicEndpoint() plus ${String(auth.length - 1)} sharedSecretAuth() policies is ${String(auth.length)}. Drop publicEndpoint() or the shared-secret policies it makes dead.`
            : `Catch channels may declare at most ${CATCH_MAX_AUTH_POLICIES} secret policies (got ${auth.length}).`);
    }
    return {
        routes: routes.map((route) => ({ method: route.method, path: route.path })),
        auth,
    };
}
/**
 * Deployment secrets the control plane decrypts to admit this channel's
 * caught requests — the names behind its `sharedSecretAuth` /
 * `hmacSignatureAuth` policies (a named GitHub webhook secret included).
 * Empty for a `publicEndpoint()` channel: that chain admits everything, so
 * the control plane checks nothing. `deploy` folds these into the declared
 * secret names so an unset one is flagged before the first delivery 401s.
 */
export function channelCatchSecretNames(definition) {
    const declaration = channelCatchDeclaration(definition);
    if (declaration === undefined || declaration.auth.some((policy) => policy.kind === "public")) {
        return [];
    }
    return [
        ...new Set(declaration.auth.flatMap((policy) => (policy.kind === "public" ? [] : [policy.secret]))),
    ];
}
/**
 * Deployment secrets a channel reads in the guest: `githubChannel`
 * `{ secretName }` credentials and a named `pagerdutyChannel` user id.
 * Nothing on the control plane reads them, but `deploy` folds them into the
 * declared secret names so an unset one is flagged at deploy time rather
 * than as a failed call or a missed check inside the guest.
 */
export function channelCredentialSecretNames(definition) {
    return [
        ...githubChannelCredentialSecretNames(definition),
        ...pagerDutyChannelCredentialSecretNames(definition),
    ];
}
/**
 * Sets of guest-read secrets a channel needs one of, such as
 * `pagerdutyChannel`'s user id or a token to infer it from. `deploy`
 * warns about a set only when none of its names is set.
 */
export function channelSecretAlternatives(definition) {
    return pagerDutyChannelSecretAlternatives(definition);
}
/**
 * Parse an untrusted manifest (round-trip check for the CLI's own output;
 * the CP re-validates server-side with its own copy of the contract).
 */
export function parseAgentDeployManifest(raw) {
    const parsed = agentDeployManifestV1Schema.safeParse(raw);
    // `info` is opaque to the wire schema (validated as a plain object) but
    // typed as AgentProjectInfo for producers/consumers inside the SDK.
    if (!parsed.success) {
        return undefined;
    }
    // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- the wire schema checks the manifest; info stays a plain object while AgentDeployManifestV1 names AgentProjectInfo
    return parsed.data;
}
